?>
<?php if ($saved): ?><div class="flash-ok" role="status">Catering event workspace saved.</div><?php endif; ?>
<?php if ($error): ?><div class="flash-error" role="alert"><?= e($error) ?></div><?php endif; ?>

<div class="page-head"><div><p class="section-kicker">Catering operations</p><h1>Events and tastings</h1><p>Accepted Core quotations are synchronized automatically. You can also promote a qualified quote request to a tentative event.</p></div><a class="btn secondary" href="<?= e_attr($basePath) ?>/admin/catering/production">Production catalog</a></div>

<section class="card">
<div class="card-heading"><div><h2>Create a tentative event</h2><p class="card-subtitle">This copies the immutable questionnaire, menu, and operations snapshots. It does not accept a Core quote or collect payment.</p></div></div>
<?php if ($inquiries !== []): ?><form method="post"><input type="hidden" name="action" value="create_event"><?= $csrf->field() ?><div class="form-grid"><label>Quote request<select name="inquiry_id" required><option value="">Choose a request</option><?php foreach ($inquiries as $inquiry): ?><option value="<?= (int)$inquiry['id'] ?>"><?= e(trim((string)$inquiry['event_date'] . ' · ' . (string)$inquiry['event_type'] . ' · ' . (string)$inquiry['name'])) ?><?= $inquiry['guest_count'] ? ' · ' . (int)$inquiry['guest_count'] . ' guests' : '' ?></option><?php endforeach; ?></select></label><div class="action-bar"><span>Core quote acceptance remains authoritative.</span><button class="btn" type="submit">Create tentative event</button></div></div></form><?php else: ?><p class="muted">Every current quote request is already represented by an event.</p><?php endif; ?>
</section>

<section class="card"><div class="card-heading"><div><h2>Event calendar</h2><p class="card-subtitle">Tentative, confirmed, completed, and cancelled events remain linked to their original request.</p></div></div>
<?php if ($events === []): ?><p class="muted">No catering events yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th scope="col">Date</th><th scope="col">Event</th><th scope="col">State</th><th scope="col">Guests</th><th scope="col">Open tasks</th><th scope="col">Action</th></tr></thead><tbody><?php foreach ($events as $event): ?><tr><td><?= e((string)($event['event_date'] ?: 'Date pending')) ?></td><th scope="row"><?= e($event['title']) ?></th><td><span class="badge"><?= e(ucfirst($event['state'])) ?></span></td><td><?= (int)($event['final_guest_count'] ?: $event['guest_count']) ?></td><td><?= (int)$event['open_tasks'] ?></td><td><a class="btn secondary" href="<?= e_attr($basePath) ?>/admin/catering/events/<?= (int)$event['id'] ?>">Open workspace</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</section>

<section class="card"><div class="card-heading"><div><h2>Tasting requests</h2><p class="card-subtitle">A request is never a scheduled appointment until staff confirms it.</p></div></div>
<?php if ($tastings === []): ?><p class="muted">No tasting requests.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th scope="col">Customer</th><th scope="col">Eligibility</th><th scope="col">Status and date</th><th scope="col">Notes</th><th scope="col">Save</th></tr></thead><tbody><?php foreach ($tastings as $tasting): $formId='tasting-'.(int)$tasting['id']; ?><tr><th scope="row"><?= e($tasting['customer_name']) ?><br><span class="muted"><?= e($tasting['customer_email']) ?></span></th><td><select form="<?=e_attr($formId)?>" name="eligibility"><option value="review"<?= $tasting['eligibility']==='review'?' selected':'' ?>>Needs review</option><option value="eligible"<?= $tasting['eligibility']==='eligible'?' selected':'' ?>>Eligible</option><option value="ineligible"<?= $tasting['eligibility']==='ineligible'?' selected':'' ?>>Ineligible</option></select></td><td><select form="<?=e_attr($formId)?>" name="status"><?php foreach (\CajunWebPro\Catering\EventWorkspace::TASTING_STATUSES as $status): ?><option value="<?= e_attr($status) ?>"<?= $tasting['status']===$status?' selected':'' ?>><?= e(ucwords(str_replace('_',' ',$status))) ?></option><?php endforeach; ?></select><input form="<?=e_attr($formId)?>" type="date" name="preferred_date" value="<?= e_attr((string)$tasting['preferred_date']) ?>"></td><td><textarea form="<?=e_attr($formId)?>" name="notes" rows="3" maxlength="5000"><?= e((string)$tasting['notes']) ?></textarea></td><td><form id="<?=e_attr($formId)?>" method="post" action="<?= e_attr($basePath) ?>/admin/catering/tastings"><?= $csrf->field() ?><input type="hidden" name="id" value="<?= (int)$tasting['id'] ?>"><button class="btn secondary" type="submit">Update</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</section>
